606	func (s Store) verifyRunProofAsSealed(proof ReviewRunProof, run ReviewRun) (ReviewRunAssurance, error) {
607		fail := func(message string) (ReviewRunAssurance, error) {
608			return ReviewRunAssurance{}, fmt.Errorf("run provenance: %s", message)
609		}
610		if _, e := s.verifyRunProofCore(proof, run); e != nil {
611			return ReviewRunAssurance{}, e
612		}
613		c, p := proof.Claim, run.Provenance
614		end, e := time.Parse(time.RFC3339Nano, run.EndedAt)
615		issued, e2 := time.Parse(time.RFC3339Nano, c.IssuedAt)
616		if e != nil || e2 != nil || issued.Before(end) {
617			return fail("proof predates the ended run")
618		}
619		if why := s.ReviewRunRecordStands(run); why != "" {
620			return fail(why)
621		}
622		bundle, e := s.LoadReviewBundle(run.BundleID)
623		if e != nil {
624			return fail("the reviewed bundle cannot be read")
625		}
626		recorded, recordErr := normalizeModelIdentity(ModelIdentity{Principal: p.Reviewer.Principal, Vendor: run.Vendor, Model: run.Model})
627		if recordErr != nil || recorded != p.Reviewer {
628			return fail("reviewer identity differs or is unknown")
629		}
630		if !validProofDigest(p.WorktreeDigest) {
631			return fail("the origin worktree of the run is not recorded")
632		}
633		switch p.ExecutionState {
634		case "started":
635			if !validProofDigest(p.ArgvDigest) || !validProofDigest(p.ExecutableDigest) || !validProofDigest(p.RawTranscriptDigest) || !validProofDigest(p.RawOutputDigest) {
636				return fail("execution or original-byte digests missing")
637			}
638			if p.WireComplete && (p.WireBytes < 0 || p.WireDigest != p.PlannedWireDigest) {
639				return fail("complete stdin claim is inconsistent")
640			}
641		case "not-started":
642			if p.WireBytes != 0 || p.WireComplete || p.WireDigest != "" || run.Status == ReviewRunCompleted || run.Status == ReviewRunInterrupted {
643				return fail("unstarted audit claims an executed or transmitted review")
644			}
645		default:
646			return fail("unknown execution observation")
647		}
648		if run.Status == ReviewRunCompleted && (!p.WireComplete || !p.OutputComplete || strings.TrimSpace(run.Output) == "") {
649			return fail("truncated or incomplete draft cannot establish completed review")
650		}
651		return runAssuranceFrom(run, proof, bundle, p.Implementation, p.Reviewer), nil
652	}
